-- Connect to pgAdmin4, as user 'akh'. Execute the following code as user 'akh' in Database 'akh' using 
--     Query Tool of PgAdmin4.
-- Database 'akh' has a table 'tourist' under public schema with three columns: id, name,location 
-- 1. Create the function using the 'http' extension syntax
CREATE OR REPLACE FUNCTION notify_n8n_webhook() 
RETURNS TRIGGER AS $$
DECLARE
    payload TEXT;
    response http_response;
BEGIN
    -- Convert the newly inserted row to text
    payload := row_to_json(NEW)::text;

    -- Send the HTTP POST request via the http extension
    -- Note the URL of your webhook is to be written below
    SELECT * INTO response FROM http_post(
        'http://192.240.4.102:5678/webhook-test/postgresWebhook',
        payload,
        'application/json'
    );

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;


-- 2. Bind it to your table
CREATE TRIGGER tr_after_insert_n8n
AFTER INSERT ON public.tourist
FOR EACH ROW
EXECUTE FUNCTION notify_n8n_webhook();

--3. Insert a row in tourist to trigger webhook
--    Webhook should already be listening.    
INSERT INTO public.tourist (id, name, location) 
VALUES (2, 'gautam', 'Delhi');
